def _yeniden_hashle(self):
    eski_kovalar = self.kovalar
    self.kovalar = [[] for _ in range(len(eski_kovalar) * 2)]
    for kova in eski_kovalar:
        for k, v in kova:
            self.kovalar[self._hash(k)].append([k, v])

def _asagi_sizdir(self, i):
    n = len(self.veri)
    sol, sag = 2 * i + 1, 2 * i + 2
    ebk = i
    if sol < n and self.veri[sol] < self.veri[ebk]:
        ebk = sol
    if sag < n and self.veri[sag] < self.veri[ebk]:
        ebk = sag
    if ebk != i:
        self.veri[i], self.veri[ebk] = self.veri[ebk], self.veri[i]

def ara(self, anahtar):
    m = self.kok
    while m is not None:
        if anahtar == m.anahtar:
            return True
        m = m.sol if anahtar > m.anahtar else m.sag
    return False
